const body = $input.item.json.body || $input.item.json;

// Extract message data from WhatsApp webhook payload
const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { skip: true } }];
}

const telefono = message.from;
const texto = message.text?.body || '';
const messageId = message.id;
const timestamp = message.timestamp;
const nombreContacto = value?.contacts?.[0]?.profile?.name || '';

return [{
  json: {
    telefono,
    texto,
    messageId,
    timestamp,
    nombreContacto,
    skip: false
  }
}];

const msgData = $('🔧 Extraer Mensaje y Teléfono').item.json;
const configData = $('📊 Obtener Config Empresa').item.json;
const waConfigData = $('⚙️ Obtener WA Config').item.json;
const leadData = $('📋 Buscar Lead Existente').item.json;

const config = configData.records?.[0]?.fields || {};
const waConfig = waConfigData.records?.[0]?.fields || {};
const bienvenida = waConfig.WA_Mensaje_Bienvenida || config.WA_Mensaje_Bienvenida || 'Hola 👋 buen día, soy el asistente de Crating Express en Miami. ¿En qué te puedo ayudar?';
const emailVendedor = config.WA_Email_Vendedor || 'risosadmi@gmail.com';
const descripcion = config['descripción_corta'] || 'Embalajes de madera a medida en Miami, FL. Cajones y cajas con certificación ISPM-15.';
const instruccionesIA = waConfig.Instrucciones_IA || config.Instrucciones_IA || '';
const promptTemplate = waConfig.Prompt_Sistema || config.Prompt_Sistema || '';
const followup24 = waConfig.WA_FollowUp_24h || config.WA_FollowUp_24h || '';
const followup72 = waConfig.WA_FollowUp_72h || config.WA_FollowUp_72h || '';

const leadExistente = leadData.records?.[0];
const leadId = leadExistente?.id || null;
const leadFields = leadExistente?.fields || {};

// Read from Respuesta_1/2/3 fields (reliable individual fields)
let datosRecolectados = {
  producto: leadFields.Respuesta_1 || null,
  medidas: leadFields.Respuesta_2 || null,
  fecha: leadFields.Respuesta_3 || null,
  tipo_cajon: null,
  proteccion_extra: null,
  direccion: null
};

// Try to supplement tipo_cajon and proteccion_extra from Notas
try {
  const notas = leadFields.Notas || '';
  if (notas && notas.trim().startsWith('{')) {
    const stored = JSON.parse(notas);
    if (stored.tipo_cajon) datosRecolectados.tipo_cajon = stored.tipo_cajon;
    if (stored.proteccion_extra) datosRecolectados.proteccion_extra = stored.proteccion_extra;
    if (stored.direccion) datosRecolectados.direccion = stored.direccion;
  }
} catch(e) {}

const estado = leadFields.Estado || 'Nuevo';
const cotizacionEnviada = ['Cotizacion_Enviada', 'Calificado', 'Vendedor notificado'].includes(estado);
const historial = leadFields.Historial_Mensajes || '';
const esNuevo = !leadId;


// Read products catalog from Airtable
const productosData = $('📦 Obtener Productos').item.json;
const productosRaw = productosData.records || [];
const catalogoProductos = productosRaw.map(r => {
  const f = r.fields;
  const nombre = Object.entries(f).find(([k]) => k.includes('Nombre de Servicio'))?.[1] || '';
  const cuando = (f['cuando_recomendar'] || '').split('\n')[0].trim();
  const noUsar = (f['cuando_no_recomendar'] || '').split('\n')[0].trim();
  return `${nombre}: ${cuando}${noUsar ? '. NO: ' + noUsar : ''}`;
}).filter(l => l.length > 2).join('\n');

// Build final prompt substituting dynamic values
const promptSistema = promptTemplate
  .replace('{{CATALOGO}}', catalogoProductos)
  .replace('{{INSTRUCCIONES}}', instruccionesIA ? 'Instrucciones adicionales: ' + instruccionesIA : '')
  .trim();

// Greeting based on Miami time (UTC-4 EDT)
const horaMiami = (new Date().getUTCHours() - 4 + 24) % 24;
const saludoHora = horaMiami >= 6 && horaMiami < 12 ? 'buenos días'
  : horaMiami >= 12 && horaMiami < 19 ? 'buenas tardes'
  : 'buenas noches';

return [{ json: {
  telefono: msgData.telefono,
  texto: msgData.texto,
  nombreContacto: msgData.nombreContacto || '',
  emailVendedor,
  descripcion,
  instruccionesIA,
  bienvenida,
  followup24,
  followup72,
  leadId,
  estado,
  historial,
  datosRecolectados,
  cotizacionEnviada,
  esNuevo,
  saludoHora,
  catalogoProductos,
  promptSistema
} }];

