// Handle OpenAI-format (Groq/DeepSeek choices) or Contingency (direct object)
const raw = $input.item.json;
let aiResponse;
if (raw._contingencia) {
  aiResponse = JSON.stringify(raw);
} else {
  aiResponse = raw.choices?.[0]?.message?.content 
    || '{}';
}
let result;
try { result = JSON.parse(aiResponse); }
catch(e) { result = { mensaje: 'Gracias por tu mensaje. Te ayudaremos con tu cotización.', datos_actualizados: {}, todos_recolectados: false, cotizador_enviado: false, clasificacion: null, resumen_lead: '' }; }

const ctx = $('🔧 Preparar Contexto IA').item.json;
const datosAnt = ctx.datosRecolectados || {};
const datosNuevos = result.datos_actualizados || {};

// Clean "desconocido", "null", empty strings → real null
const clean = (v) => (!v || v === 'desconocido' || v === 'null' || v === 'undefined') ? null : v;

const datosMerged = {
  producto: clean(datosNuevos.producto) || clean(datosAnt.producto) || null,
  medidas: clean(datosNuevos.medidas) || clean(datosAnt.medidas) || null,
  fecha: clean(datosNuevos.fecha) || clean(datosAnt.fecha) || null,
  tipo_cajon: clean(datosNuevos.tipo_cajon) || clean(datosAnt.tipo_cajon) || null,
  proteccion_extra: clean(datosNuevos.proteccion_extra) || clean(datosAnt.proteccion_extra) || null,
  direccion: clean(datosNuevos.direccion) || clean(datosAnt.direccion) || null
};

// Valid Airtable Estado options: Nuevo, En calificación, Calificado, Vendedor notificado
let nuevoEstado = ctx.estado;
if (result.cotizador_enviado && result.clasificacion === 'Caliente') nuevoEstado = 'Vendedor notificado';
else if (result.cotizador_enviado) nuevoEstado = 'Calificado';
else if (result.clasificacion === 'Caliente') nuevoEstado = 'Vendedor notificado';
else if (result.clasificacion) nuevoEstado = 'Calificado';
else if (!ctx.leadId || nuevoEstado === 'Nuevo') nuevoEstado = 'En calificación';

const ts = new Date().toISOString();
const nuevoHistorial = (ctx.historial ? ctx.historial + '\n' : '') +
  `[${ts}] Cliente: ${ctx.texto}\n[${ts}] Bot: ${result.mensaje || ''}`;

return [{ json: {
  ...ctx,
  mensajeRespuesta: result.mensaje || '',
  datosRecolectados: datosMerged,
  todosRecolectados: result.todos_recolectados || false,
  cotizadorEnviado: result.cotizador_enviado || false,
  clasificacion: result.clasificacion || null,
  resumenLead: result.resumen_lead || '',
  nuevoEstado,
  nuevoHistorial
} }];

