const ctx = $('🔧 Preparar Contexto IA').item.json;
const datos = ctx.datosRecolectados || {};
const historial = ctx.historial || '';
const texto = (ctx.texto || '').trim().toLowerCase();
const emailVendedor = ctx.emailVendedor || 'risosadmi@gmail.com';

// Detect what the last bot question was about, to map current answer
const ultimaLinea = historial.split('\n').reverse().find(l => l.includes('] Bot:')) || '';
const preguntaProducto = ultimaLinea.includes('necesitas embalar') || ultimaLinea.includes('producto necesitas');
const preguntaMedidas = ultimaLinea.includes('medidas') || ultimaLinea.includes('tamaño') || ultimaLinea.includes('largo x');
const preguntaFecha = ultimaLinea.includes('cuándo') || ultimaLinea.includes('fecha') || ultimaLinea.includes('para cuándo');

// Non-answer messages (greetings, questions, confusion)
const esSaludo = /^(hola|buenas|buenos|hey|hi|buen dia|buenas tardes|buenas noches)/i.test(ctx.texto);
const esConfusion = /^(\?+|hmm|no sé|ok|si|sí|bien|gracias)$/i.test(ctx.texto.trim());

// Map current message as answer to last question
let producto = datos.producto;
let medidas = datos.medidas;
let fecha = datos.fecha;

if (!esSaludo && !esConfusion) {
  if (preguntaProducto && !producto) producto = ctx.texto;
  else if (preguntaMedidas && !medidas) medidas = ctx.texto;
  else if (preguntaFecha && !fecha) fecha = ctx.texto;
  else if (!producto) producto = ctx.texto; // first real message = product
}

// Determine next question
let mensaje = '';
let listo = false;

if (!producto) {
  mensaje = ctx.esNuevo
    ? `${ctx.saludoHora || 'Hola'}, gracias por contactar a Crating Express. ¿Qué necesitas embalar?`
    : '¿Qué producto necesitas embalar?';
} else if (!medidas) {
  mensaje = `¿Cuáles son las medidas aproximadas y el peso? (Largo x Ancho x Alto + peso)`;
} else if (!fecha) {
  mensaje = '¿Para cuándo necesitas el servicio?';
} else {
  listo = true;
  mensaje = 'Perfecto, tenemos tu información. Un asesor te contactará en breve por este mismo WhatsApp con la cotización. 🙏';
}

const result = {
  mensaje,
  datos_actualizados: { producto, medidas, fecha,
    tipo_cajon: datos.tipo_cajon || null,
    proteccion_extra: datos.proteccion_extra || null,
    direccion: datos.direccion || null
  },
  todos_recolectados: listo,
  cotizador_enviado: false,
  clasificacion: listo ? 'Tibio' : null,
  resumen_lead: listo ? `Contingencia — ${producto}, ${medidas}, ${fecha}` : '',
  _contingencia: true
};

return [{ json: result }];

